/**
 * Typed payload codec (`distributed_game::codec`): the value encoding of
 * inputs, events and records described by a game surface. Scalar encodings
 * are the entity field encodings (`PROTOCOL.md` §4), so one value means the
 * same bytes everywhere. Code generated by `distributed game-client` drives
 * it with layout constants; hand-written code may use it directly.
 */
import { GameDecodeError, WireReader, WireWriter } from './wire.js';
import { dequantizeAngle, dequantizeLinear, quantizeAngle, quantizeLinear } from './schema.js';

export type WireType =
	| Readonly<{ type: 'bool' }>
	| Readonly<{ type: 'u8' }>
	| Readonly<{ type: 'i8' }>
	| Readonly<{ type: 'u16' }>
	| Readonly<{ type: 'i16' }>
	| Readonly<{ type: 'u32' }>
	| Readonly<{ type: 'i32' }>
	| Readonly<{ type: 'u64' }>
	| Readonly<{ type: 'f32' }>
	| Readonly<{ type: 'f64' }>
	| Readonly<{ type: 'quant'; min: number; max: number; bits: number }>
	| Readonly<{ type: 'angle'; bits: number }>
	| Readonly<{ type: 'short_str' }>
	| Readonly<{ type: 'str' }>
	| Readonly<{ type: 'bytes' }>
	| Readonly<{ type: 'list'; item: WireType }>
	| Readonly<{ type: 'optional'; item: WireType }>
	| Readonly<{ type: 'record'; fields: PayloadLayout }>;

/** Ordered `[property, type]` pairs (property names are the TS names). */
export type PayloadLayout = readonly (readonly [string, WireType])[];

const INT_RANGE: Readonly<Record<string, readonly [number, number]>> = {
	u8: [0, 255],
	i8: [-128, 127],
	u16: [0, 65535],
	i16: [-32768, 32767],
	u32: [0, 0xffff_ffff],
	i32: [-0x8000_0000, 0x7fff_ffff],
	u64: [0, Number.MAX_SAFE_INTEGER]
};

function num(value: unknown): number {
	if (typeof value === 'number') return value;
	if (typeof value === 'boolean') return value ? 1 : 0;
	return 0;
}

/** Rust `f64 as int` semantics: NaN → 0, saturating, truncating. */
function saturate(n: number, lo: number, hi: number): number {
	if (Number.isNaN(n)) return 0;
	return Math.trunc(Math.min(Math.max(n, lo), hi));
}

const utf8 = new TextEncoder();

/** Append `value` as `type`, coercing numbers into the type's range. */
export function writeWire(w: WireWriter, type: WireType, value: unknown): void {
	switch (type.type) {
		case 'bool':
			w.bool(value === true || (typeof value === 'number' && value !== 0));
			return;
		case 'u8':
			w.u8(saturate(num(value), 0, 255));
			return;
		case 'i8':
			w.u8(saturate(num(value), -128, 127) & 0xff);
			return;
		case 'u16':
		case 'u32':
			w.varuint(saturate(num(value), ...INT_RANGE[type.type]));
			return;
		case 'i16':
		case 'i32':
			w.varint(saturate(num(value), ...INT_RANGE[type.type]));
			return;
		case 'u64':
			w.varuint53(saturate(num(value), 0, Number.MAX_SAFE_INTEGER));
			return;
		case 'f32':
			w.f32(num(value));
			return;
		case 'f64':
			w.f64(num(value));
			return;
		case 'quant':
			w.varuint(quantizeLinear(num(value), type.min, type.max, type.bits));
			return;
		case 'angle':
			w.varuint(quantizeAngle(num(value), type.bits));
			return;
		case 'short_str':
			w.shortString(typeof value === 'string' ? value : '');
			return;
		case 'str':
			w.string(typeof value === 'string' ? value : '');
			return;
		case 'bytes':
			w.bytes(
				value instanceof Uint8Array
					? value
					: typeof value === 'string'
						? utf8.encode(value)
						: Array.isArray(value)
							? Uint8Array.from(value as number[])
							: new Uint8Array(0)
			);
			return;
		case 'list': {
			const items = Array.isArray(value) ? value : [];
			w.varuint(items.length);
			for (const item of items) writeWire(w, type.item, item);
			return;
		}
		case 'optional':
			if (value === undefined || value === null) {
				w.u8(0);
			} else {
				w.u8(1);
				writeWire(w, type.item, value);
			}
			return;
		case 'record': {
			const object = (value ?? {}) as Record<string, unknown>;
			for (const [name, field] of type.fields) writeWire(w, field, object[name]);
			return;
		}
	}
}

/** Read one value of `type` (optional `none` decodes as `undefined`). */
export function readWire(r: WireReader, type: WireType): unknown {
	switch (type.type) {
		case 'bool':
			return r.bool();
		case 'u8':
			return r.u8();
		case 'i8': {
			const byte = r.u8();
			return byte > 127 ? byte - 256 : byte;
		}
		case 'u16': {
			const v = r.varuint();
			if (v > 65535) throw new GameDecodeError('INVALID', 'u16 out of range');
			return v;
		}
		case 'i16': {
			const v = r.varint();
			if (v < -32768 || v > 32767) throw new GameDecodeError('INVALID', 'i16 out of range');
			return v;
		}
		case 'u32':
			return r.varuint();
		case 'i32':
			return r.varint();
		case 'u64':
			return r.varuint53();
		case 'f32':
			return r.f32();
		case 'f64':
			return r.f64();
		case 'quant': {
			const q = r.varuint();
			if (q > 2 ** type.bits - 1) {
				throw new GameDecodeError('INVALID', 'quantized value out of range');
			}
			return dequantizeLinear(q, type.min, type.max, type.bits);
		}
		case 'angle': {
			const q = r.varuint();
			if (q >= 2 ** type.bits) throw new GameDecodeError('INVALID', 'angle out of range');
			return dequantizeAngle(q, type.bits);
		}
		case 'short_str':
			return r.shortString();
		case 'str':
			return r.string();
		case 'bytes':
			return r.bytes();
		case 'list': {
			const count = r.varuint();
			if (count > r.remaining) throw new GameDecodeError('UNEXPECTED_EOF', 'list longer than input');
			const out: unknown[] = [];
			for (let i = 0; i < count; i += 1) out.push(readWire(r, type.item));
			return out;
		}
		case 'optional': {
			const tag = r.u8();
			if (tag === 0) return undefined;
			if (tag === 1) return readWire(r, type.item);
			throw new GameDecodeError('INVALID', 'option tag must be 0 or 1');
		}
		case 'record':
			return readFields(r, type.fields);
	}
}

function readFields(r: WireReader, layout: PayloadLayout): Record<string, unknown> {
	const out: Record<string, unknown> = {};
	for (const [name, type] of layout) out[name] = readWire(r, type);
	return out;
}

/** Encode an object field by field. */
export function encodePayload(layout: PayloadLayout, value: object): Uint8Array {
	const w = new WireWriter();
	const object = value as Record<string, unknown>;
	for (const [name, type] of layout) writeWire(w, type, object[name]);
	return w.finish();
}

/** Decode a whole payload (trailing bytes are an error). */
export function decodePayload(layout: PayloadLayout, payload: Uint8Array): Record<string, unknown> {
	const r = new WireReader(payload);
	const out = readFields(r, layout);
	r.finish();
	return out;
}

/** Encode one value (a `Variant(T)` event payload). */
export function encodeValue(type: WireType, value: unknown): Uint8Array {
	const w = new WireWriter();
	writeWire(w, type, value);
	return w.finish();
}

/** Decode one whole value. */
export function decodeValue(type: WireType, payload: Uint8Array): unknown {
	const r = new WireReader(payload);
	const out = readWire(r, type);
	r.finish();
	return out;
}

/** What the receiver decodes for `value` (encode → decode). */
export function canonicalWire(type: WireType, value: unknown): unknown {
	return decodeValue(type, encodeValue(type, value));
}

/** One input field's server-side sanitize rule. */
export type InputRule =
	| Readonly<{ range: readonly [number, number] }>
	| Readonly<{ buttons: number }>
	| undefined;

/**
 * Mirror of the server's `GameInput::from_payload`: what the zone will
 * simulate for `input` (wire coercion, then `#[range]` clamp, `#[buttons]`
 * mask; a non-finite float rejects the whole input → `undefined`).
 */
export function sanitizePayload<T extends object>(
	layout: PayloadLayout,
	rules: readonly InputRule[],
	input: T
): T | undefined {
	const decoded = decodePayload(layout, encodePayload(layout, input));
	const object = input as Record<string, unknown>;
	for (let i = 0; i < layout.length; i += 1) {
		const [name, type] = layout[i];
		const rule = rules[i];
		let v = decoded[name];
		if (type.type === 'f32' || type.type === 'f64') {
			const raw = num(object[name]);
			if (!Number.isFinite(raw)) return undefined;
		}
		if (typeof v === 'number' && rule !== undefined) {
			if ('range' in rule) {
				v = Math.min(Math.max(v, rule.range[0]), rule.range[1]);
				if (type.type !== 'f32' && type.type !== 'f64' && type.type !== 'quant' && type.type !== 'angle') {
					v = Math.trunc(v as number);
				} else {
					v = Math.fround(v as number);
				}
			} else {
				v = (v & rule.buttons) >>> 0;
			}
		}
		decoded[name] = v;
	}
	return decoded as T;
}
